labspec=[
('L1','Build the production request path','A React frontend and Spring Boot API must run behind an HTTPS edge.','Deploy both workloads and verify browser → ingress → API → health path.',['Build React assets','Build Spring Boot image','Deploy workloads','Configure ingress','Run browser smoke test'],['kubectl get pods,svc,ingress','kubectl rollout status deployment/api']),
('L1','Add PostgreSQL with safe configuration','The API needs durable data without exposing the database publicly.','Connect the API to a private PostgreSQL endpoint using runtime configuration and health checks.',['Create database','Configure private access','Inject credentials','Run migration','Verify read/write'],['kubectl exec deploy/api -- printenv | grep DB_HOST','psql "$DATABASE_URL" -c "select 1"']),
('L2','Build a GitHub Actions delivery pipeline','Every merge should produce one tested immutable container artifact.','Build, test, scan and publish a commit-addressed image.',['Trigger on PR/main','Run tests','Build image','Scan image','Push digest'],['docker build -t ghcr.io/org/api:$GITHUB_SHA .','docker inspect ghcr.io/org/api:$GITHUB_SHA']),
('L2','Deploy to Kubernetes from Actions','A trusted image must move from registry to staging automatically.','Use OIDC and a narrowly scoped deployment identity to update the staging workload.',['Configure OIDC trust','Authenticate','Update image','Wait for rollout','Smoke test'],['kubectl set image deployment/api api=ghcr.io/org/api:$GITHUB_SHA','kubectl rollout status deployment/api']),
('L2','Implement canary release','A new API version needs controlled production exposure.','Expose a small traffic slice and promote only when health gates pass.',['Deploy candidate','Route 5%','Observe','Promote to 25%','Abort on threshold'],['# conceptual: 5% → 25% → 50% → 100%']),
('L2','Debug a production 502','Users report 502 after an ingress change.','Find the first failing boundary and restore service without guessing.',['Check ingress','Check service endpoints','Check targetPort','Check pod readiness','Validate listener'],['kubectl describe ingress api','kubectl get endpoints api','kubectl logs deploy/api --tail=100']),
('L2','Debug CrashLoopBackOff','A new API pod restarts continuously.','Use events, previous logs, probes and configuration to identify the cause.',['Inspect events','Read previous logs','Check env/secret','Check probes','Roll back if needed'],['kubectl logs pod/api-xxx --previous','kubectl describe pod api-xxx']),
('L2','Handle database saturation','PostgreSQL CPU and connections spike after a release.','Protect the database and identify the query/concurrency regression.',['Check DB metrics','Inspect pool','Find slow queries','Reduce concurrency','Verify recovery'],['SELECT * FROM pg_stat_activity;','# inspect query plan with EXPLAIN (ANALYZE, BUFFERS)']),
('L2','Recover from bad deployment','Error rate rises immediately after production rollout.','Pause promotion and roll back the immutable artifact while preserving evidence.',['Freeze rollout','Check error/trace metrics','Rollback','Verify recovery','Capture incident timeline'],['kubectl rollout undo deployment/api','kubectl rollout status deployment/api']),
('L2','Perform backward-compatible DB migration','Two application versions coexist during a rolling deployment.','Expand schema, deploy compatible code, backfill and contract later.',['Add nullable/new structure','Deploy dual-read/write code','Backfill','Verify','Remove old path later'],['ALTER TABLE orders ADD COLUMN status_v2 text;']),
('L2','Trace a slow request','Users report high p95 latency but CPU is normal.','Use a trace to locate the slow downstream operation.',['Capture trace','Break down spans','Check DB/dependency','Fix bottleneck','Verify p95'],['# trace: React → API → service → DB','EXPLAIN (ANALYZE, BUFFERS) ...']),
('L3','Simulate node failure','A Kubernetes node becomes unavailable.','Verify replica rescheduling and data/service continuity.',['Drain/fail node in test','Observe scheduling','Check service endpoints','Validate persistent data','Measure recovery'],['kubectl get nodes','kubectl get pods -o wide','kubectl get events --sort-by=.lastTimestamp']),
('L3','Test graceful shutdown','A rolling deployment is dropping long-running requests.','Implement readiness-first shutdown and verify in-flight request behavior.',['Enable readiness','Configure termination grace','Send long request','Roll deployment','Verify completion'],['kubectl rollout restart deployment/api','kubectl describe pod api-xxx']),
('L3','Secure production identities','CI and pods currently use broad credentials.','Replace long-lived keys and broad roles with scoped identities.',['Inventory permissions','Create OIDC trust','Scope deployment role','Create workload identity','Test denied actions'],['aws sts get-caller-identity','kubectl auth can-i get secrets']),
('L3','Build observability dashboard','The team cannot correlate deployments with user impact.','Create a minimum dashboard and alerts for traffic, errors, latency and saturation.',['Choose RED metrics','Add infrastructure signals','Add deployment markers','Create alerts','Test alert path'],['rate(http_requests_total[5m])','histogram_quantile(0.95, ...)']),
('L3','Disaster recovery drill','The primary database is unavailable.','Execute the documented recovery path and measure RTO/RPO.',['Declare incident','Validate backup/replica','Restore/fail over','Repoint application','Measure RTO/RPO'],['# record recovery start/end timestamps','SELECT now();']),
('L3','Cost optimization review','Cloud cost has increased without matching traffic growth.','Find waste while preserving SLOs.',['Break down spend','Check utilization','Right-size','Review storage lifecycle','Validate after change'],['aws ce get-cost-and-usage --time-period Start=...','kubectl top pods']),
('L3','Production security incident','A CI credential may have been exposed.','Contain, rotate, audit and validate the affected path.',['Disable/rotate credential','Review workflow logs','Check artifact provenance','Audit cloud actions','Restore least privilege'],['git log --all -- .github/workflows','aws cloudtrail lookup-events ...']),
('L3','Design the complete capstone','Multiple teams need independent releases for React/Spring Boot services.','Design a secure, observable, recoverable platform with clear ownership.',['Define boundaries','Choose cloud primitives','Define delivery','Define failure handling','Define SLOs/runbooks'],['GitHub → Actions → Registry → Kubernetes → DB → Observability']),
('L3','Incident interview drill','An interviewer gives a cascading failure with incomplete information.','Explain your diagnosis, mitigation, evidence and prevention in a structured answer.',['Clarify impact','State hypothesis','Collect evidence','Mitigate','Prevent recurrence'],['impact → evidence → mitigation → root cause → prevention'])]

def labtuple(idx,s):
    level,title,situation,goal,steps,commands=s
    return {'id':f'capstone-lab-{idx:03d}','level':level,'title':title,'situation':situation,'goal':goal,'steps':steps,'commands':commands,'delivery':f'I would execute this as a controlled production-style exercise: establish impact, gather evidence, make the smallest safe change, verify recovery and capture what we learned.','followups':['What would you verify first?','How would you prevent recurrence?'],'followupAnswers':['I start at the first observable boundary: user impact, workload state, routing, dependency health and recent changes, then narrow using evidence.','I add the appropriate guardrail—test, alert, policy, rollout gate, capacity control or runbook—based on the failure mechanism rather than the symptom.'],'traps':['Do not make multiple unrelated changes before you know which one fixed the issue.']}
labs=[labtuple(i+1,s) for i,s in enumerate(labspec)]

# Write JS with valid JSON-ish JS export.
def js(v): return json.dumps(v,ensure_ascii=False,indent=2)
(root/'src/data/capstoneLessons.js').write_text('export const capstoneLessons = '+js(lessons)+';\n')
(root/'src/data/capstoneLabs.js').write_text('export const capstoneLabs = '+js(labs)+';\n')

page='''import React, { useMemo, useState } from "react";\nimport { capstoneLessons } from "../data/capstoneLessons";\nimport { capstoneLabs } from "../data/capstoneLabs";\n\nfunction Card({ item, open, onToggle, lab }) {\n  const followups = item.followups || [];\n  return <article className="lesson-card scenario-card">\n    <button className="lesson-head" onClick={onToggle}>\n      <span className="q-number">{item.id.split("-").pop()}</span>\n      <span className="lesson-title"><strong>{item.title}</strong><span className="meta"><i className="level">{item.level}</i><i>{lab ? "Capstone Lab" : item.topic}</i></span></span>\n      <span className="chevron">{open ? "⌃" : "⌄"}</span>\n    </button>\n    {open && <div className="lesson-body scenario-body">\n      <div className="explain-section"><div className="section-kicker">{lab ? "SITUATION" : "WHAT IS IT?"}</div><p>{lab ? item.situation : item.what}</p></div>\n      <div className="explain-section"><div className="section-kicker">{lab ? "GOAL / APPROACH" : "HOW IT WORKS"}</div><p>{lab ? item.goal : item.how}</p></div>\n      <div className="explain-section"><div className="section-kicker">{lab ? "STEPS / COMMANDS" : "WORKFLOW / EXAMPLE"}</div>\n        {lab ? <><ol className="mistake-list" style={{marginBottom:10}}>{item.steps.map((s,i)=><li key={i}>{s}</li>)}</ol><pre>{item.commands.join("\\n")}</pre></> : <pre>{item.code}</pre>}\n      </div>\n      <div className="explain-section interview-script"><span className="script-label">INTERVIEW DELIVERY</span><p>{item.delivery}</p></div>\n      <div className="explain-section"><div className="section-kicker">EXPECTED FOLLOW-UPS</div><div className="followup-list">{followups.map((q,i)=><details className="followup-item" key={i}><summary>{q}</summary><div className="followup-answer"><strong>ANSWER</strong><p>{item.followupAnswers?.[i]}</p></div></details>)}</div></div>\n      <div className="explain-section mistake-section"><div className="section-kicker">{lab ? "LAB TRAPS" : "INTERVIEW TRAPS"}</div><ul className="mistake-list">{item.traps.map((t,i)=><li key={i}>{t}</li>)}</ul></div>\n    </div>}\n  </article>;\n}\n\nexport default function ProductionEngineeringLearning() {\n const [tab,setTab]=useState("learn"),[level,setLevel]=useState("all"),[query,setQuery]=useState(""),[open,setOpen]=useState({});\n const source=tab==="learn"?capstoneLessons:capstoneLabs;\n const filtered=useMemo(()=>source.filter(x=>(level==="all"||x.level===level)&&JSON.stringify(x).toLowerCase().includes(query.toLowerCase())),[source,level,query]);\n const expandAll=()=>setOpen(Object.fromEntries(filtered.map(x=>[x.id,true])));\n return <section className="learning-page">\n  <div className="learning-hero scenario-hero"><span className="pill">V20 · END-TO-END PRODUCTION ENGINEERING</span><h2>Build it.<br/><em>Break it. Operate it.</em></h2><p>Bring React, Spring Boot, PostgreSQL, Docker, Kubernetes, GitHub Actions and cloud deployment together into one production engineering capstone. Learn to design, deploy, observe, debug, recover and explain the system under failure.</p><div className="learning-flow"><span>Build</span><b>→</b><span>Test</span><b>→</b><span>Ship</span><b>→</b><span>Deploy</span><b>→</b><span>Observe</span><b>→</b><span>Break</span><b>→</b><span>Recover</span><b>→</b><span>Explain</span></div></div>\n  <div className="learning-toolbar"><div className="search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search architecture, Kubernetes, AWS, rollback, database, observability, incidents..."/></div><div className="filters">{["all","L1","L2","L3"].map(x=><button key={x} className={level===x?"filter active":"filter"} onClick={()=>setLevel(x)}>{x==="all"?"All levels":x}</button>)}</div></div>\n  <div className="subtopic-row"><button className={tab==="learn"?"subtopic active":"subtopic"} onClick={()=>{setTab("learn");setOpen({})}}>🏗 Learn Production <small>{capstoneLessons.length}</small></button><button className={tab==="labs"?"subtopic active":"subtopic"} onClick={()=>{setTab("labs");setOpen({})}}>🛠 Capstone Labs <small>{capstoneLabs.length}</small></button></div>\n  <div className="result-row"><span><b>{tab==="learn"?"Production Lessons":"Capstone Labs"}</b> · {filtered.length} items</span><button onClick={expandAll}>Expand all</button><button onClick={()=>setOpen({})}>Collapse all</button></div>\n  <section className="lesson-list">{filtered.map(x=><Card key={x.id} item={x} lab={tab==="labs"} open={!!open[x.id]} onToggle={()=>setOpen(p=>({...p,[x.id]:!p[x.id]}))}/>)}</section>\n </section>;\n}\n'''
(root/'src/pages/ProductionEngineeringLearning.jsx').write_text(page)

# patch App, Header, Sidebar
p=root/'src/App.jsx'; s=p.read_text(); s=s.replace('import CloudLearning from "./pages/CloudLearning";','import CloudLearning from "./pages/CloudLearning";\nimport ProductionEngineeringLearning from "./pages/ProductionEngineeringLearning";'); s=s.replace(': view === "cloud" ? <CloudLearning /> :', ': view === "cloud" ? <CloudLearning /> : view === "production" ? <ProductionEngineeringLearning /> :'); p.write_text(s)
p=root/'src/components/Sidebar.jsx'; s=p.read_text(); s=s.replace('import { cloudLabs } from "../data/cloudLabs";','import { cloudLabs } from "../data/cloudLabs";\nimport { capstoneLessons } from "../data/capstoneLessons";\nimport { capstoneLabs } from "../data/capstoneLabs";'); needle='''            <button className={view === "cloud" ? "nav-item active" : "nav-item"} onClick={() => go("cloud")}>\n              <span>☁</span><label>Cloud & Deployment</label><small>{cloudLessons.length + cloudLabs.length}</small>\n            </button>'''; repl=needle+'''\n            <button className={view === "production" ? "nav-item active" : "nav-item"} onClick={() => go("production")}>\n              <span>🏗</span><label>Production Engineering</label><small>{capstoneLessons.length + capstoneLabs.length}</small>\n            </button>'''; s=s.replace(needle,repl); p.write_text(s)
p=root/'src/components/Header.jsx'; s=p.read_text(); s=s.replace('import { cloudLabs } from "../data/cloudLabs";','import { cloudLabs } from "../data/cloudLabs";\nimport { capstoneLessons } from "../data/capstoneLessons";\nimport { capstoneLabs } from "../data/capstoneLabs";'); s=s.replace('const cloud = view === "cloud";','const cloud = view === "cloud";\n  const production = view === "production";'); s=s.replace(': cloud ? "Cloud & Deployment Learning" : "Backend Interview Preparation";', ': cloud ? "Cloud & Deployment Learning" : production ? "Production Engineering" : "Backend Interview Preparation";'); s=s.replace('                          : "Java · Spring Boot · Microservices · SQL · JPA · Security · Cloud · System Design";', '                          : production\n                            ? "React · Spring Boot · PostgreSQL · Docker · Kubernetes · GitHub Actions · Cloud · Observability · Reliability"\n                            : "Java · Spring Boot · Microservices · SQL · JPA · Security · Cloud · System Design";'); s=s.replace(': cloud ? `${cloudLessons.length + cloudLabs.length} CLOUD ITEMS` : `${questions.length} QUESTIONS`;', ': cloud ? `${cloudLessons.length + cloudLabs.length} CLOUD ITEMS` : production ? `${capstoneLessons.length + capstoneLabs.length} CAPSTONE ITEMS` : `${questions.length} QUESTIONS`;'); s=s.replace(': cloud ? "cloud@deployment:~" : "backend@interview:~"', ': cloud ? "cloud@deployment:~" : production ? "production@engineering:~" : "backend@interview:~"'); p.write_text(s)

# package + notes
